import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { AwsClient } from 'aws4fetch';
import type { Config, S3Config } from '../config.js';

/** Where uploaded documents live. Keys are generated by the server (`documents/<id>/<sha>`), never by users. */
export interface FileStore {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]*$/i;

function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('Invalid storage key');
}

export function localFileStore(dir: string): FileStore {
  const root = resolve(dir);
  const pathFor = (key: string) => {
    assertSafeKey(key);
    const path = resolve(join(root, key));
    if (!path.startsWith(root + sep)) throw new Error('Invalid storage key');
    return path;
  };
  return {
    async put(key, bytes) {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, bytes);
    },
    async get(key) {
      try {
        return new Uint8Array(await readFile(pathFor(key)));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    },
  };
}

/**
 * Amazon S3, Cloudflare R2 or any S3-compatible service, signed with SigV4. Requests go straight to the bucket with
 * the server's own keys; give those keys access to this one bucket only.
 */
export function s3FileStore(options: S3Config, doFetch: typeof fetch = fetch): FileStore {
  const client = new AwsClient({
    accessKeyId: options.accessKeyId,
    secretAccessKey: options.secretAccessKey,
    service: 's3',
    region: options.region,
  });
  const base = options.endpoint
    ? `${options.endpoint.replace(/\/+$/, '')}/${options.bucket}`
    : `https://${options.bucket}.s3.${options.region}.amazonaws.com`;
  const urlFor = (key: string) => {
    assertSafeKey(key);
    return `${base}/${key.split('/').map(encodeURIComponent).join('/')}`;
  };
  const send = async (url: string, init?: RequestInit) => doFetch(await client.sign(url, init));
  // S3 error bodies are XML with a <Code> (AccessDenied, NoSuchBucket...): keep it, it says what to fix.
  const failure = async (action: string, res: Response) => {
    const code = (await res.text().catch(() => '')).match(/<Code>([A-Za-z]+)<\/Code>/)?.[1];
    // On a wrong region, AWS says where the bucket really is.
    const actualRegion = res.headers.get('x-amz-bucket-region');
    const where = actualRegion && actualRegion !== options.region ? `; the bucket is in ${actualRegion}` : '';
    return new Error(`${options.provider} ${action} failed (${res.status}${code ? ` ${code}` : ''})${where}`);
  };
  return {
    async put(key, bytes, contentType) {
      const res = await send(urlFor(key), { method: 'PUT', body: bytes, headers: { 'content-type': contentType } });
      if (!res.ok) throw await failure('upload', res);
    },
    async get(key) {
      const res = await send(urlFor(key));
      if (res.status === 404) return null;
      if (!res.ok) throw await failure('download', res);
      return new Uint8Array(await res.arrayBuffer());
    },
  };
}

export function memoryFileStore(): FileStore {
  const files = new Map<string, Uint8Array>();
  return {
    async put(key, bytes) {
      assertSafeKey(key);
      files.set(key, bytes);
    },
    async get(key) {
      return files.get(key) ?? null;
    },
  };
}

export function createFileStore(config: Config): FileStore {
  return config.storage.kind === 's3' ? s3FileStore(config.storage) : localFileStore(config.storage.dir);
}
